const raw = $input.first().json?.choices?.[0]?.message?.content ?? '{}';
let data = {};
try { data = JSON.parse(raw); } catch (e) { data = {}; }
const str = (v, max) => (typeof v === 'string' ? v : '').replace(/\s+/g, ' ').trim().slice(0, max);
const fields = {
  fullName: str(data.fullName, 120),
  phone: str(data.phone, 30),
  industry: str(data.industry, 120),
};
const digits = fields.phone.replace(/\D/g, '').length;
const missing = [];
if (fields.fullName.length < 2) missing.push('fullName');
if (digits < 6) missing.push('phone');
if (fields.industry.length < 2) missing.push('industry');
return [{ json: { fields, missing, complete: missing.length === 0 } }];

const transcript = String($('Transcribe Audio').first().json?.text ?? '').trim();
const raw = $input.first().json?.choices?.[0]?.message?.content ?? '{}';
let data = {};
try { data = JSON.parse(raw); } catch (e) { data = {}; }
const LIMITS = { fullName: 120, jobTitle: 120, companyName: 160, industry: 120, email: 160, phone: 30, website: 200, instagram: 200, facebook: 200, linkedin: 200, tiktok: 200, notes: 1000, interestCompany: 160 };
const fields = {};
for (const [key, max] of Object.entries(LIMITS)) {
  const value = typeof data[key] === 'string' ? data[key] : '';
  fields[key] = (key === 'notes' ? value.trim() : value.replace(/\s+/g, ' ').trim()).slice(0, max);
}
fields.email = fields.email.replace(/\s+/g, '').toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(fields.email)) fields.email = '';
fields.website = fields.website.replace(/\s+/g, '').toLowerCase();
const phoneDigits = fields.phone.replace(/\D/g, '').length;
const missing = [];
if (fields.fullName.length < 2) missing.push('fullName');
if (fields.companyName.length < 2) missing.push('companyName');
if (fields.industry.length < 2) missing.push('industry');
if (fields.email === '' && phoneDigits < 6) missing.push('contact');
return [{ json: { transcript, fields, missing } }];
